{
  "interpretation": {
    "name": "TightenFastenersLine2AndReturnTool",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Tighten the fasteners of variant F30 at station st2 of line 2 with the shared nutrunner NR7, then return the tool to the crib and release the reservation so other lines are not blocked.",
    "constraints": [
      "NR7 must be reserved before any use and released after it has been returned",
      "NR7 must be transported to st2 (transport-tool completed) before configure-tool and tighten-fasteners",
      "transport-tool must be delegated to the Executor agvexecutor",
      "The tightening program must be obtained from get-program, with no numeric process values in the Recipe",
      "The tightening must be evaluated and recorded for traceability (quality policy E5)",
      "Every tool-using Step renews the lease and therefore depends on reserve-tool",
      "The tool is returned to the crib before the reservation is released"
    ],
    "preference": "Release the shared tool as soon as possible after use",
    "priority": "normal",
    "horizon": "Single execution, now",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-tighten-and-return-nr7",
    "first_action": "Prepare",
    "actions": [
      {
        "name": "Prepare",
        "next": "BringTool",
        "steps": [
          {"name": "reserve", "service": "reserve-tool", "next": [], "dep": [], "executor": null, "params": {}},
          {"name": "program", "service": "get-program", "next": [], "dep": [], "executor": null, "params": {}}
        ]
      },
      {
        "name": "BringTool",
        "next": "Tighten",
        "steps": [
          {"name": "transport-to-station", "service": "transport-tool", "next": [], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "station"}}
        ]
      },
      {
        "name": "Tighten",
        "next": "EvaluateAndReturn",
        "steps": [
          {"name": "configure", "service": "configure-tool", "next": ["tighten"], "dep": ["program", "reserve", "transport-to-station"], "executor": null, "params": {}},
          {"name": "tighten", "service": "tighten-fasteners", "next": [], "dep": ["configure", "reserve"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "EvaluateAndReturn",
        "next": "ReleaseTool",
        "steps": [
          {"name": "evaluate", "service": "evaluate-tightening", "next": [], "dep": ["tighten", "program"], "executor": null, "params": {}},
          {"name": "record", "service": "record-tightening", "next": [], "dep": ["tighten"], "executor": null, "params": {}},
          {"name": "transport-to-crib", "service": "transport-tool", "next": [], "dep": ["reserve", "tighten"], "executor": "agvexecutor", "params": {"to": "crib"}}
        ]
      },
      {
        "name": "ReleaseTool",
        "next": null,
        "steps": [
          {"name": "release", "service": "release-tool", "next": [], "dep": ["reserve", "transport-to-crib"], "executor": null, "params": {}}
        ]
      }
    ]
  }
}
